INSERT INTO public.mini_app_subtopics (mini_app_id, title, slug, icon, content_md, ordem) VALUES ('3b689d95-0730-4bb5-a47a-7fd59ddaa624', 'Vasoativos', 'vasoativos', '💉', '# 💉 Drogas Vasoativas\n\nEste guia foca na segurança beira-leito, diluições padronizadas e monitorização crítica.\n\n--- \n\n## 👑 1. Noradrenalina (Rainha do Choque)\n\n**Mecanismo:** Agonista α1 potente (vasoconstrição) e β1 leve. Aumenta a PAM sem grandes aumentos de FC.\n\n**Indicação:** Primeira linha no choque séptico e outros choques vasodilatadores.\n\n**Diluição Padrão (ADEC):**\n> 4 ampolas (16mg) + 250ml de SG 5% → Concentração: **64 mcg/mL**\n\n**Dose:**\n* Iniciar: 0,05 a 0,1 mcg/kg/min.\n* Titular a cada 5-10 min conforme PAM alvo (geralmente ≥ 65 mmHg).\n\n**Cuidados Críticos:**\n* **Acesso Central:** Obrigatório (risco alto de necrose por extravasamento).\n* **Fotossensibilidade:** Exige equipo e capa fotoprotetora (âmbar).\n* **Desmame:** Nunca desligar abruptamente (risco de hipotensão rebote).\n\n--- \n\n## 🧡 2. Dobutamina (O Inotrópico)\n\n**Mecanismo:** Agonista β1 predominante. Aumenta a força (inotrópismo) e a frequência (cronotropismo).\n\n**⚠️ REGRA DE OURO:** Não é droga para pressão! Pode causar vasodilatação (β2) e queda da PAM. Se a pressão estiver baixa, deve estar associada à Noradrenalina.\n\n**Diluição Padrão:**\n> 1 ampola (250mg) + 250ml de SG 5% ou SF 0,9% → Concentração: **1.000 mcg/mL**\n\n**Dose:** 2,5 a 20 mcg/kg/min.\n\n**Cuidados Críticos:**\n* **Taquifilaxia:** Perda de efeito após ~72h de uso contínuo.\n* **Controle de Diurese:** O aumento do volume urinário é o melhor sinal de que o débito cardíaco melhorou.\n* **Arritmias:** Monitorização contínua obrigatória.', 1);
